create function private.install_finance_payroll_permissions(requested_organization_id uuid) returns void language plpgsql security definer set search_path='' as $$
begin
 insert into public.role_permissions(role_id,permission_id)
 select role.id,permission.id from public.roles role cross join public.permissions permission
 where role.organization_id=requested_organization_id and role.key in('owner','administrator') and (permission.key like 'accounting.%' or permission.key like 'compliance.%' or permission.key like 'payroll.%') on conflict do nothing;
 insert into public.role_permissions(role_id,permission_id)
 select role.id,permission.id from public.roles role join public.permissions permission on permission.key=any(array['accounting.read','accounting.reconcile','compliance.read','payroll.read','payroll.manage'])
 where role.organization_id=requested_organization_id and role.key='manager' on conflict do nothing;
 insert into public.role_permissions(role_id,permission_id)
 select role.id,permission.id from public.roles role join public.permissions permission on permission.key=any(array['accounting.read','compliance.read','payroll.read'])
 where role.organization_id=requested_organization_id and role.key='viewer' on conflict do nothing;
end;$$;
create function private.handle_main_branch_finance_payroll_permissions() returns trigger language plpgsql security definer set search_path='' as $$begin if new.code='main' then perform private.install_finance_payroll_permissions(new.organization_id);end if;return new;end;$$;
create trigger zzzzzzzzzz_install_finance_payroll_permissions after insert on public.branches for each row execute function private.handle_main_branch_finance_payroll_permissions();
select private.install_finance_payroll_permissions(id) from public.organizations;

create function private.accounting_module_enabled(requested_organization_id uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='accounting');
$$;

create table public.accounting_settings(
 organization_id uuid primary key references public.organizations(id) on delete cascade,
 status text not null default 'shadow' check(status in('shadow','active','suspended')),activation_date date,
 currency text not null default 'PHP' check(currency='PHP'),cash_flow_method text not null default 'indirect' check(cash_flow_method='indirect'),
 posting_detail text not null default 'document' check(posting_detail in('summary','document')),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.accounting_accounts(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,parent_id uuid,
 code text not null,name text not null,account_type text not null check(account_type in('asset','liability','equity','revenue','expense','contra_revenue','contra_asset')),
 normal_balance text not null check(normal_balance in('debit','credit')),system_key text,is_control boolean not null default false,is_active boolean not null default true,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,code),unique(organization_id,system_key),
 foreign key(parent_id,organization_id) references public.accounting_accounts(id,organization_id) on delete restrict,
 check(char_length(btrim(code)) between 3 and 20 and char_length(btrim(name)) between 2 and 160)
);
create table public.accounting_periods(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,fiscal_year integer not null,period_number integer not null check(period_number between 1 and 12),
 starts_on date not null,ends_on date not null,status text not null default 'open' check(status in('open','closed')),closed_at timestamptz,closed_by uuid references auth.users(id),created_at timestamptz not null default now(),
 unique(id,organization_id),unique(organization_id,starts_on),check(ends_on>=starts_on)
);
create table public.accounting_document_sequences(organization_id uuid not null references public.organizations(id) on delete cascade,document_type text not null,year integer not null,last_number bigint not null default 0,primary key(organization_id,document_type,year));
create table public.journal_entries(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,period_id uuid not null,
 journal_number text not null,entry_date date not null,status text not null default 'posted' check(status in('draft','posted','reversed','rejected')),
 source_type text not null,source_id uuid,source_key text not null,description text not null,currency text not null default 'PHP' check(currency='PHP'),
 reversal_of_id uuid,reversed_by_id uuid,posted_at timestamptz,posted_by uuid references auth.users(id),created_at timestamptz not null default now(),
 unique(id,organization_id),unique(organization_id,journal_number),unique(organization_id,source_key),
 foreign key(branch_id,organization_id) references public.branches(id,organization_id) on delete restrict,foreign key(period_id,organization_id) references public.accounting_periods(id,organization_id) on delete restrict,
 foreign key(reversal_of_id,organization_id) references public.journal_entries(id,organization_id) on delete restrict,foreign key(reversed_by_id,organization_id) references public.journal_entries(id,organization_id) on delete restrict
);
create table public.journal_lines(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,entry_id uuid not null,account_id uuid not null,position integer not null,
 description text not null default'',debit numeric(18,4) not null default 0,credit numeric(18,4) not null default 0,branch_id uuid,customer_id uuid,supplier_id uuid,employee_id uuid,bank_account_id uuid,
 created_at timestamptz not null default now(),unique(entry_id,position),foreign key(entry_id,organization_id) references public.journal_entries(id,organization_id) on delete restrict,
 foreign key(account_id,organization_id) references public.accounting_accounts(id,organization_id) on delete restrict,
 foreign key(branch_id,organization_id) references public.branches(id,organization_id) on delete restrict,
 foreign key(customer_id,organization_id) references public.sales_customers(id,organization_id) on delete restrict,
 foreign key(supplier_id,organization_id) references public.suppliers(id,organization_id) on delete restrict,
 foreign key(employee_id,organization_id) references public.employees(id,organization_id) on delete restrict,
 check((debit>0 and credit=0)or(credit>0 and debit=0))
);
create table public.accounting_posting_exceptions(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,event_id uuid,event_key text not null,error_code text not null,message text not null,
 status text not null default 'open' check(status in('open','resolved','dismissed')),attempt_count integer not null default 1,details jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz,resolved_by uuid references auth.users(id),unique(organization_id,event_key)
);
create table public.opening_balance_imports(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,cutover_date date not null,status text not null default 'draft' check(status in('draft','posted','rejected')),
 payload_hash text not null,entry_id uuid,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),posted_at timestamptz,unique(organization_id,payload_hash),foreign key(entry_id,organization_id) references public.journal_entries(id,organization_id) on delete restrict
);

alter table public.supplier_invoices add column amount_paid numeric(16,4) not null default 0 check(amount_paid>=0),add column balance_due numeric(16,4) not null default 0 check(balance_due>=0);
update public.supplier_invoices set balance_due=case when status='cancelled' then 0 else total end;
create table public.supplier_payments(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid not null,supplier_id uuid not null,payment_date date not null,payment_method text not null check(payment_method in('cash','bank_transfer','card','digital_wallet','cheque','other')),reference text,amount numeric(16,4) not null check(amount>0),unapplied_amount numeric(16,4) not null check(unapplied_amount>=0),idempotency_key text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,idempotency_key),foreign key(branch_id,organization_id) references public.branches(id,organization_id),foreign key(supplier_id,organization_id) references public.suppliers(id,organization_id)
);
create table public.supplier_payment_allocations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,payment_id uuid not null,supplier_invoice_id uuid not null,amount numeric(16,4) not null check(amount>0),created_at timestamptz not null default now(),unique(payment_id,supplier_invoice_id),foreign key(payment_id,organization_id) references public.supplier_payments(id,organization_id),foreign key(supplier_invoice_id,organization_id) references public.supplier_invoices(id,organization_id));

create table public.bank_accounts(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,name text not null,bank_name text not null,account_last_four text not null check(account_last_four~'^[0-9]{4}$'),currency text not null default'PHP'check(currency='PHP'),opening_balance numeric(18,4) not null default 0,is_active boolean not null default true,ledger_account_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),foreign key(branch_id,organization_id) references public.branches(id,organization_id),foreign key(ledger_account_id,organization_id) references public.accounting_accounts(id,organization_id)
);
alter table public.journal_lines add constraint journal_lines_bank_account_fk foreign key(bank_account_id,organization_id) references public.bank_accounts(id,organization_id) on delete restrict;
create table public.bank_transactions(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,bank_account_id uuid not null,transaction_date date not null,description text not null,reference text,amount numeric(18,4) not null check(amount<>0),external_key text not null,status text not null default'unmatched'check(status in('unmatched','partially_matched','matched','excluded')),imported_at timestamptz not null default now(),unique(id,organization_id),unique(bank_account_id,external_key),foreign key(bank_account_id,organization_id) references public.bank_accounts(id,organization_id)
);
create table public.bank_reconciliations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,bank_account_id uuid not null,period_end date not null,statement_ending_balance numeric(18,4) not null,status text not null default'draft'check(status in('draft','completed','reopened')),book_balance numeric(18,4),difference numeric(18,4),completed_at timestamptz,completed_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),unique(bank_account_id,period_end),foreign key(bank_account_id,organization_id) references public.bank_accounts(id,organization_id)
);
create table public.bank_reconciliation_matches(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,reconciliation_id uuid not null,bank_transaction_id uuid not null,journal_line_id uuid not null,amount numeric(18,4) not null check(amount>0),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(reconciliation_id,bank_transaction_id,journal_line_id),foreign key(reconciliation_id,organization_id) references public.bank_reconciliations(id,organization_id),foreign key(bank_transaction_id,organization_id) references public.bank_transactions(id,organization_id),foreign key(journal_line_id) references public.journal_lines(id)
);

create index journal_entries_period_idx on public.journal_entries(organization_id,entry_date,status);create index journal_lines_account_idx on public.journal_lines(organization_id,account_id,entry_id);create index accounting_exceptions_open_idx on public.accounting_posting_exceptions(organization_id,created_at) where status='open';create index supplier_invoice_aging_idx on public.supplier_invoices(organization_id,due_date,status) where balance_due>0;create index bank_transactions_unmatched_idx on public.bank_transactions(bank_account_id,transaction_date) where status in('unmatched','partially_matched');
create trigger set_updated_at before update on public.accounting_settings for each row execute function private.set_updated_at();create trigger set_updated_at before update on public.accounting_accounts for each row execute function private.set_updated_at();create trigger set_updated_at before update on public.accounting_posting_exceptions for each row execute function private.set_updated_at();create trigger set_updated_at before update on public.bank_accounts for each row execute function private.set_updated_at();
create function private.initialize_supplier_invoice_balance()returns trigger language plpgsql set search_path='' as $$begin if new.status='cancelled'then new.balance_due:=0;else new.balance_due:=new.total-new.amount_paid;end if;return new;end;$$;create trigger initialize_supplier_invoice_balance before insert on public.supplier_invoices for each row execute function private.initialize_supplier_invoice_balance();

create function private.seed_accounting_accounts(requested_organization_id uuid) returns void language plpgsql security definer set search_path='' as $$
begin
 insert into public.accounting_settings(organization_id) values(requested_organization_id) on conflict do nothing;
 insert into public.accounting_accounts(organization_id,code,name,account_type,normal_balance,system_key,is_control) values
  (requested_organization_id,'1000','Cash on Hand','asset','debit','cash',true),(requested_organization_id,'1010','Cash in Bank','asset','debit','bank',true),(requested_organization_id,'1020','Digital Payment Clearing','asset','debit','digital_clearing',true),
  (requested_organization_id,'1100','Accounts Receivable','asset','debit','accounts_receivable',true),(requested_organization_id,'1150','Input VAT','asset','debit','input_tax',true),(requested_organization_id,'1200','Inventory','asset','debit','inventory',true),
  (requested_organization_id,'2000','Accounts Payable','liability','credit','accounts_payable',true),(requested_organization_id,'2050','Goods Received Not Invoiced','liability','credit','grni',true),(requested_organization_id,'2100','Output VAT','liability','credit','output_tax',true),
  (requested_organization_id,'2110','Withholding Tax Payable','liability','credit','withholding_payable',true),(requested_organization_id,'2120','SSS Payable','liability','credit','sss_payable',true),(requested_organization_id,'2130','PhilHealth Payable','liability','credit','philhealth_payable',true),(requested_organization_id,'2140','Pag-IBIG Payable','liability','credit','pagibig_payable',true),(requested_organization_id,'2150','Payroll Payable','liability','credit','payroll_payable',true),(requested_organization_id,'2160','Employee Deductions Payable','liability','credit','employee_deductions_payable',true),(requested_organization_id,'2200','Customer Advances','liability','credit','customer_advances',true),
  (requested_organization_id,'3000','Owner Equity','equity','credit','owner_equity',true),(requested_organization_id,'3100','Retained Earnings','equity','credit','retained_earnings',true),
  (requested_organization_id,'4000','Sales Revenue','revenue','credit','sales_revenue',true),(requested_organization_id,'4050','Sales Returns and Allowances','contra_revenue','debit','sales_returns',true),
  (requested_organization_id,'5000','Cost of Goods Sold','expense','debit','cogs',true),(requested_organization_id,'6000','Operating Expenses','expense','debit','operating_expense',true),(requested_organization_id,'6100','Salaries and Wages','expense','debit','salary_expense',true),(requested_organization_id,'6110','Allowances and Commissions','expense','debit','allowance_expense',true),(requested_organization_id,'6120','Employer Contributions','expense','debit','employer_contribution_expense',true)
 on conflict(organization_id,code) do nothing;
end;$$;
create function private.handle_accounting_module_activation() returns trigger language plpgsql security definer set search_path='' as $$declare module_key text;begin select key into module_key from public.module_definitions where id=new.module_id;if module_key='accounting'and new.is_enabled then perform private.seed_accounting_accounts(new.organization_id);end if;return new;end;$$;
create trigger seed_accounting_on_module_activation after insert or update of is_enabled on public.organization_modules for each row execute function private.handle_accounting_module_activation();

create function private.next_accounting_number(requested_organization_id uuid,requested_type text,requested_date date) returns text language plpgsql security definer set search_path='' as $$declare value bigint;yr integer:=extract(year from requested_date);begin insert into public.accounting_document_sequences(organization_id,document_type,year,last_number)values(requested_organization_id,requested_type,yr,1)on conflict(organization_id,document_type,year)do update set last_number=public.accounting_document_sequences.last_number+1 returning last_number into value;if value is null then value:=1;end if;return upper(requested_type)||'-'||yr||'-'||lpad(value::text,7,'0');end;$$;
create function private.account_by_key(requested_organization_id uuid,requested_key text) returns uuid language sql stable security definer set search_path='' as $$select id from public.accounting_accounts where organization_id=requested_organization_id and system_key=requested_key and is_active;$$;

create function private.ensure_accounting_periods(requested_organization_id uuid,requested_date date) returns void language plpgsql security definer set search_path='' as $$declare month_start date;month_value date;idx integer;begin month_start:=(date_trunc('year',requested_date)::date-interval'12 months')::date;for idx in 0..47 loop month_value:=(month_start+(idx||' months')::interval)::date;insert into public.accounting_periods(organization_id,fiscal_year,period_number,starts_on,ends_on)values(requested_organization_id,extract(year from month_value)::integer,extract(month from month_value)::integer,month_value,(month_value+interval'1 month'-interval'1 day')::date)on conflict(organization_id,starts_on)do nothing;end loop;end;$$;

create function private.post_journal(requested_organization_id uuid,requested_branch_id uuid,requested_entry_date date,requested_source_type text,requested_source_id uuid,requested_source_key text,requested_description text,requested_lines jsonb,requested_actor uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare target_id uuid;period_row public.accounting_periods%rowtype;item jsonb;debit_sum numeric:=0;credit_sum numeric:=0;position_value integer:=0;account_id_value uuid;debit_value numeric;credit_value numeric;
begin
 select id into target_id from public.journal_entries where organization_id=requested_organization_id and source_key=requested_source_key;if found then return target_id;end if;
 if requested_entry_date is null or jsonb_typeof(requested_lines)<>'array'or jsonb_array_length(requested_lines)<2 then raise exception'Invalid journal.'using errcode='22023';end if;
 perform private.ensure_accounting_periods(requested_organization_id,requested_entry_date);select*into period_row from public.accounting_periods where organization_id=requested_organization_id and requested_entry_date between starts_on and ends_on for update;
 if period_row.id is null or period_row.status<>'open'then raise exception'Accounting period is closed.'using errcode='P0001';end if;
 insert into public.journal_entries(organization_id,branch_id,period_id,journal_number,entry_date,status,source_type,source_id,source_key,description,posted_at,posted_by)
 values(requested_organization_id,requested_branch_id,period_row.id,private.next_accounting_number(requested_organization_id,'je',requested_entry_date),requested_entry_date,'draft',requested_source_type,requested_source_id,requested_source_key,btrim(requested_description),null,requested_actor)returning id into target_id;
 for item in select value from jsonb_array_elements(requested_lines) loop
  account_id_value:=private.account_by_key(requested_organization_id,item->>'accountKey');debit_value:=round(coalesce((item->>'debit')::numeric,0),4);credit_value:=round(coalesce((item->>'credit')::numeric,0),4);
  if account_id_value is null or not((debit_value>0 and credit_value=0)or(credit_value>0 and debit_value=0))then raise exception'Invalid journal line.'using errcode='22023';end if;
  insert into public.journal_lines(organization_id,entry_id,account_id,position,description,debit,credit,branch_id,customer_id,supplier_id,employee_id)
  values(requested_organization_id,target_id,account_id_value,position_value,coalesce(item->>'description',''),debit_value,credit_value,coalesce((item->>'branchId')::uuid,requested_branch_id),(item->>'customerId')::uuid,(item->>'supplierId')::uuid,(item->>'employeeId')::uuid);
  position_value:=position_value+1;debit_sum:=debit_sum+debit_value;credit_sum:=credit_sum+credit_value;
 end loop;
 if debit_sum<>credit_sum or debit_sum<=0 then raise exception'Journal is not balanced.'using errcode='23514';end if;
 update public.journal_entries set status='posted',posted_at=now()where id=target_id;return target_id;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception'Invalid journal data.'using errcode='22023';end;$$;

create function private.reverse_journal(requested_organization_id uuid,requested_entry_id uuid,requested_date date,requested_reason text,requested_actor uuid) returns uuid language plpgsql security definer set search_path='' as $$declare original public.journal_entries%rowtype;lines jsonb;target_id uuid;begin select*into original from public.journal_entries where id=requested_entry_id and organization_id=requested_organization_id for update;if original.id is null or original.status<>'posted'or char_length(btrim(requested_reason))not between 3 and 500 then raise exception'Journal cannot be reversed.'using errcode='P0001';end if;select jsonb_agg(jsonb_build_object('accountKey',account.system_key,'debit',line.credit,'credit',line.debit,'description','Reversal: '||line.description,'branchId',line.branch_id,'customerId',line.customer_id,'supplierId',line.supplier_id,'employeeId',line.employee_id)order by line.position)into lines from public.journal_lines line join public.accounting_accounts account on account.id=line.account_id where line.entry_id=original.id;target_id:=private.post_journal(requested_organization_id,original.branch_id,requested_date,'reversal',original.id,'reversal:'||original.id,btrim(requested_reason),lines,requested_actor);perform set_config('app.accounting_reversal','on',true);update public.journal_entries set status='reversed',reversed_by_id=target_id where id=original.id;update public.journal_entries set reversal_of_id=original.id where id=target_id;perform set_config('app.accounting_reversal','off',true);return target_id;end;$$;

create function private.reject_posted_journal_mutation() returns trigger language plpgsql set search_path='' as $$begin if tg_op='DELETE'or(old.status in('posted','reversed')and coalesce(current_setting('app.accounting_reversal',true),'off')<>'on')then raise exception'Posted journals are immutable.'using errcode='42501';end if;return case when tg_op='DELETE'then old else new end;end;$$;
create trigger journal_entries_immutable before update or delete on public.journal_entries for each row execute function private.reject_posted_journal_mutation();
create function private.reject_journal_line_mutation() returns trigger language plpgsql set search_path='' as $$begin raise exception'Journal lines are immutable.'using errcode='42501';end;$$;create trigger journal_lines_immutable before update or delete on public.journal_lines for each row execute function private.reject_journal_line_mutation();

create function private.emit_operational_accounting_event() returns trigger language plpgsql security definer set search_path='' as $$
declare event_key text;event_type_value text;aggregate_type_value text;aggregate_id_value uuid;org uuid;payload_value jsonb:='{}';
begin
 if tg_table_name='sales_audit_events' then if new.event='completed'then event_key:='sale:completed:'||new.sale_id;event_type_value:='sale.completed';aggregate_type_value:='sale';aggregate_id_value:=new.sale_id;org:=new.organization_id;else return new;end if;
 elsif tg_table_name='sales_returns' then if new.total>0 and old.total=0 then event_key:='sale:return:'||new.id;event_type_value:='sale.returned';aggregate_type_value:='sales_return';aggregate_id_value:=new.id;org:=new.organization_id;else return new;end if;
 elsif tg_table_name='expenses' then if new.approval_status='approved'and old.approval_status is distinct from new.approval_status then event_key:='expense:approved:'||new.id;event_type_value:='expense.approved';aggregate_type_value:='expense';aggregate_id_value:=new.id;org:=new.organization_id;else return new;end if;
 elsif tg_table_name='supplier_invoices' then if new.status='issued'then event_key:='supplier-invoice:issued:'||new.id;event_type_value:='supplier_invoice.issued';aggregate_type_value:='supplier_invoice';aggregate_id_value:=new.id;org:=new.organization_id;else return new;end if;
 elsif tg_table_name='purchasing_audit_history' then if new.entity_type='goods_receipt'and new.event='received'then event_key:='goods-receipt:received:'||new.entity_id;event_type_value:='goods_receipt.received';aggregate_type_value:='goods_receipt';aggregate_id_value:=new.entity_id;org:=new.organization_id;else return new;end if;
 else return new;end if;
 if private.accounting_module_enabled(org)then perform private.emit_accounting_event(org,event_key,event_type_value,aggregate_type_value,aggregate_id_value,payload_value);end if;return new;
end;$$;
create trigger emit_sale_accounting_event after insert on public.sales_audit_events for each row execute function private.emit_operational_accounting_event();
create trigger emit_return_accounting_event after update of total on public.sales_returns for each row execute function private.emit_operational_accounting_event();
create trigger emit_expense_accounting_event after update of approval_status on public.expenses for each row execute function private.emit_operational_accounting_event();
create trigger emit_supplier_invoice_accounting_event after insert on public.supplier_invoices for each row execute function private.emit_operational_accounting_event();
create trigger emit_goods_receipt_accounting_event after insert on public.purchasing_audit_history for each row execute function private.emit_operational_accounting_event();

create function private.post_accounting_event(requested_event_id uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare event_row public.accounting_integration_events%rowtype;settings_row public.accounting_settings%rowtype;entry_id uuid;lines jsonb;branch uuid;entry_date date;total_value numeric;tax_value numeric;subtotal_value numeric;cogs_value numeric;allocated_value numeric;unapplied_value numeric;method_value text;source_sale uuid;
begin
 select*into event_row from public.accounting_integration_events where id=requested_event_id for update;if event_row.id is null then raise exception'Accounting event not found.'using errcode='P0001';end if;if event_row.processing_status='processed'then select id into entry_id from public.journal_entries where organization_id=event_row.organization_id and source_key=event_row.event_key;return entry_id;end if;
 select*into settings_row from public.accounting_settings where organization_id=event_row.organization_id;if settings_row.activation_date is null then raise exception'Accounting cutover is not active.'using errcode='P0001';end if;
 if event_row.event_type='sale.completed'then
  select branch_id,completed_at::date,total,tax_total into branch,entry_date,total_value,tax_value from public.sales_transactions where id=event_row.aggregate_id and organization_id=event_row.organization_id;
  select coalesce(sum(quantity*unit_cost),0)into cogs_value from public.sales_lines where sale_id=event_row.aggregate_id;
  select jsonb_build_array(jsonb_build_object('accountKey',case when exists(select 1 from public.sales_payments where sale_id=event_row.aggregate_id and payment_method='digital')then'digital_clearing'else'cash'end,'debit',total_value,'credit',0),jsonb_build_object('accountKey','sales_revenue','debit',0,'credit',total_value-tax_value),jsonb_build_object('accountKey','output_tax','debit',0,'credit',tax_value),jsonb_build_object('accountKey','cogs','debit',cogs_value,'credit',0),jsonb_build_object('accountKey','inventory','debit',0,'credit',cogs_value))into lines;
 elsif event_row.event_type='invoice.issued'then
  select branch_id,invoice_date,total,tax_total,source_id into branch,entry_date,total_value,tax_value,source_sale from public.invoices where id=event_row.aggregate_id and organization_id=event_row.organization_id;
  if source_sale is not null then update public.accounting_integration_events set processing_status='processed',processed_at=now()where id=event_row.id;return null;end if;
  lines:=jsonb_build_array(jsonb_build_object('accountKey','accounts_receivable','debit',total_value,'credit',0),jsonb_build_object('accountKey','sales_revenue','debit',0,'credit',total_value-tax_value),jsonb_build_object('accountKey','output_tax','debit',0,'credit',tax_value));
 elsif event_row.event_type='payment.recorded'then
  select branch_id,payment_date,amount,unapplied_amount,payment_method into branch,entry_date,total_value,unapplied_value,method_value from public.ar_payments where id=event_row.aggregate_id and organization_id=event_row.organization_id;allocated_value:=total_value-unapplied_value;
  lines:=jsonb_build_array(jsonb_build_object('accountKey',case when method_value='cash'then'cash'else'bank'end,'debit',total_value,'credit',0),jsonb_build_object('accountKey','accounts_receivable','debit',0,'credit',allocated_value),jsonb_build_object('accountKey','customer_advances','debit',0,'credit',unapplied_value));
 elsif event_row.event_type='expense.approved'then
  select branch_id,expense_date,amount,payment_method into branch,entry_date,total_value,method_value from public.expenses where id=event_row.aggregate_id and organization_id=event_row.organization_id;lines:=jsonb_build_array(jsonb_build_object('accountKey','operating_expense','debit',total_value,'credit',0),jsonb_build_object('accountKey',case when method_value='cash'then'cash'else'bank'end,'debit',0,'credit',total_value));
 elsif event_row.event_type='goods_receipt.received'then
  select branch_id,received_at::date into branch,entry_date from public.goods_receipts where id=event_row.aggregate_id and organization_id=event_row.organization_id;select coalesce(sum(quantity_received*unit_cost),0)into total_value from public.goods_receipt_lines where goods_receipt_id=event_row.aggregate_id;lines:=jsonb_build_array(jsonb_build_object('accountKey','inventory','debit',total_value,'credit',0),jsonb_build_object('accountKey','grni','debit',0,'credit',total_value));
 elsif event_row.event_type='supplier_invoice.issued'then
  select branch_id,invoice_date,subtotal,tax_total,total into branch,entry_date,subtotal_value,tax_value,total_value from public.supplier_invoices where id=event_row.aggregate_id and organization_id=event_row.organization_id;lines:=jsonb_build_array(jsonb_build_object('accountKey','grni','debit',subtotal_value,'credit',0),jsonb_build_object('accountKey','input_tax','debit',tax_value,'credit',0),jsonb_build_object('accountKey','accounts_payable','debit',0,'credit',total_value));
 elsif event_row.event_type='supplier_payment.recorded'then
  select branch_id,payment_date,amount,payment_method into branch,entry_date,total_value,method_value from public.supplier_payments where id=event_row.aggregate_id and organization_id=event_row.organization_id;lines:=jsonb_build_array(jsonb_build_object('accountKey','accounts_payable','debit',total_value,'credit',0),jsonb_build_object('accountKey',case when method_value='cash'then'cash'else'bank'end,'debit',0,'credit',total_value));
 elsif event_row.event_type='invoice.cancelled'then select id into entry_id from public.journal_entries where organization_id=event_row.organization_id and source_key='invoice:issued:'||event_row.aggregate_id;if entry_id is null then update public.accounting_integration_events set processing_status='processed',processed_at=now()where id=event_row.id;return null;end if;entry_id:=private.reverse_journal(event_row.organization_id,entry_id,current_date,'Invoice cancelled',null);update public.accounting_integration_events set processing_status='processed',processed_at=now()where id=event_row.id;return entry_id;
 else raise exception'Unsupported accounting event: %',event_row.event_type using errcode='P0001';end if;
 if entry_date<settings_row.activation_date then update public.accounting_integration_events set processing_status='processed',processed_at=now()where id=event_row.id;return null;end if;
 entry_id:=private.post_journal(event_row.organization_id,branch,entry_date,event_row.event_type,event_row.aggregate_id,event_row.event_key,event_row.event_type,lines,null);update public.accounting_integration_events set processing_status='processed',processed_at=now(),last_error=null where id=event_row.id;return entry_id;
end;$$;

create function public.process_accounting_events(requested_organization_id uuid,requested_limit integer default 50) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());event_row record;processed integer:=0;failed integer:=0;begin if actor is null or not private.accounting_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'accounting.post',null)then raise exception'Permission denied.'using errcode='42501';end if;if requested_limit not between 1 and 200 then raise exception'Invalid limit.'using errcode='22023';end if;
 for event_row in select id,event_key from public.accounting_integration_events where organization_id=requested_organization_id and processing_status in('pending','failed')order by created_at,id limit requested_limit for update skip locked loop
  begin update public.accounting_integration_events set processing_status='processing',attempt_count=attempt_count+1 where id=event_row.id;perform private.post_accounting_event(event_row.id);delete from public.accounting_posting_exceptions where organization_id=requested_organization_id and event_key=event_row.event_key;processed:=processed+1;
  exception when others then update public.accounting_integration_events set processing_status='failed',last_error=left(sqlerrm,500)where id=event_row.id;insert into public.accounting_posting_exceptions(organization_id,event_id,event_key,error_code,message,details)values(requested_organization_id,event_row.id,event_row.event_key,sqlstate,left(sqlerrm,500),jsonb_build_object('sqlstate',sqlstate))on conflict(organization_id,event_key)do update set error_code=excluded.error_code,message=excluded.message,attempt_count=public.accounting_posting_exceptions.attempt_count+1,updated_at=now();failed:=failed+1;end;
 end loop;return jsonb_build_object('processed',processed,'failed',failed);end;$$;

create function public.activate_accounting(requested_organization_id uuid,requested_cutover_date date,requested_lines jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());computed_hash text;import_id_value uuid;entry_id_value uuid;debits numeric;credits numeric;begin if actor is null or not private.accounting_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'accounting.configure',null)then raise exception'Permission denied.'using errcode='42501';end if;if requested_cutover_date>current_date or jsonb_typeof(requested_lines)<>'array'or jsonb_array_length(requested_lines)<2 then raise exception'Invalid opening balances.'using errcode='22023';end if;select coalesce(sum((value->>'debit')::numeric),0),coalesce(sum((value->>'credit')::numeric),0)into debits,credits from jsonb_array_elements(requested_lines);if round(debits,4)<>round(credits,4)or debits<=0 then raise exception'Opening balances are not balanced.'using errcode='23514';end if;computed_hash:=encode(extensions.digest(requested_lines::text||requested_cutover_date::text,'sha256'),'hex');select import.id,import.entry_id into import_id_value,entry_id_value from public.opening_balance_imports import where import.organization_id=requested_organization_id and import.payload_hash=computed_hash;if import_id_value is not null then return entry_id_value;end if;insert into public.opening_balance_imports(organization_id,cutover_date,payload_hash,created_by)values(requested_organization_id,requested_cutover_date,computed_hash,actor)returning id into import_id_value;entry_id_value:=private.post_journal(requested_organization_id,null,requested_cutover_date,'opening_balance',import_id_value,'opening-balance:'||import_id_value,'Reviewed opening balances',requested_lines,actor);update public.opening_balance_imports set status='posted',entry_id=entry_id_value,posted_at=now()where id=import_id_value;update public.accounting_settings set status='active',activation_date=requested_cutover_date where organization_id=requested_organization_id;return entry_id_value;end;$$;
create function public.save_manual_journal(requested_organization_id uuid,requested_branch_id uuid,requested_entry_date date,requested_description text,requested_lines jsonb,requested_idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());begin if actor is null or not private.accounting_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'accounting.post',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if char_length(btrim(requested_description))not between 3 and 500 or char_length(btrim(requested_idempotency_key))not between 8 and 200 then raise exception'Invalid manual journal.'using errcode='22023';end if;return private.post_journal(requested_organization_id,requested_branch_id,requested_entry_date,'manual',null,'manual:'||requested_idempotency_key,requested_description,requested_lines,actor);end;$$;
create function public.reverse_journal(requested_organization_id uuid,requested_entry_id uuid,requested_date date,requested_reason text) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());begin if actor is null or not private.accounting_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'accounting.post',null)then raise exception'Permission denied.'using errcode='42501';end if;return private.reverse_journal(requested_organization_id,requested_entry_id,requested_date,requested_reason,actor);end;$$;
create function public.set_accounting_period_status(requested_organization_id uuid,requested_period_id uuid,requested_status text) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());begin if actor is null or not private.accounting_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'accounting.close',null)then raise exception'Permission denied.'using errcode='42501';end if;if requested_status not in('open','closed')then raise exception'Invalid period status.'using errcode='22023';end if;update public.accounting_periods set status=requested_status,closed_at=case when requested_status='closed'then now()end,closed_by=case when requested_status='closed'then actor end where id=requested_period_id and organization_id=requested_organization_id;if not found then raise exception'Accounting period not found.'using errcode='P0001';end if;end;$$;

create function public.record_supplier_payment(requested_organization_id uuid,requested_branch_id uuid,requested_supplier_id uuid,requested_payment_date date,requested_method text,requested_reference text,requested_amount numeric,requested_allocations jsonb,requested_idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());target_id uuid;item jsonb;invoice public.supplier_invoices%rowtype;allocated numeric:=0;allocation_value numeric;begin select id into target_id from public.supplier_payments where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if found then return target_id;end if;if actor is null or not private.accounting_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'accounting.post',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if requested_amount<=0 or requested_method not in('cash','bank_transfer','card','digital_wallet','cheque','other')or jsonb_typeof(requested_allocations)<>'array'then raise exception'Invalid supplier payment.'using errcode='22023';end if;for item in select allocation.item_value from jsonb_array_elements(requested_allocations)as allocation(item_value)order by allocation.item_value->>'supplierInvoiceId'loop select*into invoice from public.supplier_invoices where id=(item->>'supplierInvoiceId')::uuid and organization_id=requested_organization_id for update;allocation_value:=(item->>'amount')::numeric;if invoice.id is null or invoice.supplier_id<>requested_supplier_id or invoice.branch_id<>requested_branch_id or allocation_value<=0 or allocation_value>invoice.balance_due then raise exception'Invalid supplier allocation.'using errcode='P0001';end if;allocated:=allocated+allocation_value;end loop;if allocated>requested_amount then raise exception'Allocations exceed payment.'using errcode='P0001';end if;insert into public.supplier_payments(organization_id,branch_id,supplier_id,payment_date,payment_method,reference,amount,unapplied_amount,idempotency_key,created_by)values(requested_organization_id,requested_branch_id,requested_supplier_id,requested_payment_date,requested_method,nullif(btrim(requested_reference),''),requested_amount,requested_amount-allocated,requested_idempotency_key,actor)returning id into target_id;for item in select allocation.item_value from jsonb_array_elements(requested_allocations)as allocation(item_value)loop allocation_value:=(item->>'amount')::numeric;insert into public.supplier_payment_allocations(organization_id,payment_id,supplier_invoice_id,amount)values(requested_organization_id,target_id,(item->>'supplierInvoiceId')::uuid,allocation_value);update public.supplier_invoices set amount_paid=amount_paid+allocation_value,balance_due=balance_due-allocation_value,status=case when balance_due-allocation_value=0 then'paid'else'partially_paid'end where id=(item->>'supplierInvoiceId')::uuid;end loop;perform private.emit_accounting_event(requested_organization_id,'supplier-payment:recorded:'||target_id,'supplier_payment.recorded','supplier_payment',target_id,jsonb_build_object('amount',requested_amount));return target_id;end;$$;

create function public.save_bank_account(requested_organization_id uuid,requested_bank_account_id uuid,requested_branch_id uuid,requested_name text,requested_bank_name text,requested_last_four text,requested_opening_balance numeric) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());target_id uuid:=coalesce(requested_bank_account_id,gen_random_uuid());ledger uuid;begin if actor is null or not private.accounting_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'accounting.reconcile',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if requested_last_four!~'^[0-9]{4}$'or char_length(btrim(requested_name))not between 2 and 120 then raise exception'Invalid bank account.'using errcode='22023';end if;ledger:=private.account_by_key(requested_organization_id,'bank');insert into public.bank_accounts(id,organization_id,branch_id,name,bank_name,account_last_four,opening_balance,ledger_account_id)values(target_id,requested_organization_id,requested_branch_id,btrim(requested_name),btrim(requested_bank_name),requested_last_four,requested_opening_balance,ledger)on conflict(id)do update set branch_id=excluded.branch_id,name=excluded.name,bank_name=excluded.bank_name,account_last_four=excluded.account_last_four,opening_balance=excluded.opening_balance;return target_id;end;$$;
create function public.import_bank_transactions(requested_organization_id uuid,requested_bank_account_id uuid,requested_transactions jsonb) returns integer language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());branch uuid;item jsonb;count_value integer:=0;begin select branch_id into branch from public.bank_accounts where id=requested_bank_account_id and organization_id=requested_organization_id;if actor is null or branch is null or not private.can_business_permission(requested_organization_id,'accounting.reconcile',branch)then raise exception'Permission denied.'using errcode='42501';end if;if jsonb_typeof(requested_transactions)<>'array'or jsonb_array_length(requested_transactions)>5000 then raise exception'Invalid bank import.'using errcode='22023';end if;for item in select value from jsonb_array_elements(requested_transactions)loop insert into public.bank_transactions(organization_id,bank_account_id,transaction_date,description,reference,amount,external_key)values(requested_organization_id,requested_bank_account_id,(item->>'date')::date,btrim(item->>'description'),nullif(btrim(item->>'reference'),''),(item->>'amount')::numeric,item->>'externalKey')on conflict(bank_account_id,external_key)do nothing;if found then count_value:=count_value+1;end if;end loop;return count_value;end;$$;
create function public.complete_bank_reconciliation(requested_organization_id uuid,requested_bank_account_id uuid,requested_period_end date,requested_statement_balance numeric,requested_matches jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());branch uuid;target_id uuid;item jsonb;book numeric;matched numeric:=0;begin select branch_id into branch from public.bank_accounts where id=requested_bank_account_id and organization_id=requested_organization_id;if actor is null or branch is null or not private.can_business_permission(requested_organization_id,'accounting.reconcile',branch)then raise exception'Permission denied.'using errcode='42501';end if;insert into public.bank_reconciliations(organization_id,bank_account_id,period_end,statement_ending_balance)values(requested_organization_id,requested_bank_account_id,requested_period_end,requested_statement_balance)on conflict(bank_account_id,period_end)do update set statement_ending_balance=excluded.statement_ending_balance,status='draft'returning id into target_id;delete from public.bank_reconciliation_matches where reconciliation_id=target_id;for item in select value from jsonb_array_elements(requested_matches)loop insert into public.bank_reconciliation_matches(organization_id,reconciliation_id,bank_transaction_id,journal_line_id,amount,created_by)values(requested_organization_id,target_id,(item->>'bankTransactionId')::uuid,(item->>'journalLineId')::uuid,(item->>'amount')::numeric,actor);matched:=matched+(item->>'amount')::numeric;update public.bank_transactions set status='matched'where id=(item->>'bankTransactionId')::uuid and organization_id=requested_organization_id;end loop;select account.opening_balance+coalesce(sum(line.debit-line.credit),0)into book from public.bank_accounts account left join public.journal_lines line on line.account_id=account.ledger_account_id left join public.journal_entries entry on entry.id=line.entry_id and entry.status in('posted','reversed')and entry.entry_date<=requested_period_end where account.id=requested_bank_account_id group by account.opening_balance;update public.bank_reconciliations set status=case when round(requested_statement_balance-book,4)=0 then'completed'else'draft'end,book_balance=book,difference=requested_statement_balance-book,completed_at=case when round(requested_statement_balance-book,4)=0 then now()end,completed_by=case when round(requested_statement_balance-book,4)=0 then actor end where id=target_id;return target_id;end;$$;

create function public.financial_report(requested_organization_id uuid,requested_report text,requested_from date,requested_to date,requested_branch_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin if(select auth.uid())is null or not private.accounting_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'accounting.read',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if requested_report not in('trial_balance','profit_loss','balance_sheet','cash_flow')or requested_to<requested_from then raise exception'Invalid financial report.'using errcode='22023';end if;with balances as(select account.code,account.name,account.account_type,account.normal_balance,sum(line.debit)debit,sum(line.credit)credit from public.journal_entries entry join public.journal_lines line on line.entry_id=entry.id join public.accounting_accounts account on account.id=line.account_id where entry.organization_id=requested_organization_id and entry.status in('posted','reversed')and entry.entry_date between case when requested_report in('balance_sheet','cash_flow')then date'1900-01-01'else requested_from end and requested_to and(requested_branch_id is null or coalesce(line.branch_id,entry.branch_id)=requested_branch_id)group by account.code,account.name,account.account_type,account.normal_balance),filtered as(select*,case when normal_balance='debit'then debit-credit else credit-debit end balance from balances where requested_report='trial_balance'or(requested_report='profit_loss'and account_type in('revenue','expense','contra_revenue'))or(requested_report in('balance_sheet','cash_flow')and account_type in('asset','liability','equity','contra_asset')))select jsonb_build_object('report',requested_report,'from',requested_from,'to',requested_to,'currency','PHP','rows',coalesce(jsonb_agg(jsonb_build_object('code',code,'name',name,'type',account_type,'debit',debit,'credit',credit,'balance',balance)order by code),'[]'),'totalDebit',coalesce(sum(debit),0),'totalCredit',coalesce(sum(credit),0))into result from filtered;return result;end;$$;
create function public.general_ledger(requested_organization_id uuid,requested_account_id uuid,requested_from date,requested_to date,requested_branch_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin if(select auth.uid())is null or not private.accounting_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'accounting.read',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;select jsonb_build_object('accountId',requested_account_id,'from',requested_from,'to',requested_to,'items',coalesce(jsonb_agg(jsonb_build_object('entryId',entry.id,'number',entry.journal_number,'date',entry.entry_date,'description',entry.description,'sourceType',entry.source_type,'sourceId',entry.source_id,'debit',line.debit,'credit',line.credit)order by entry.entry_date,entry.journal_number,line.position),'[]'))into result from public.journal_lines line join public.journal_entries entry on entry.id=line.entry_id where line.organization_id=requested_organization_id and line.account_id=requested_account_id and entry.entry_date between requested_from and requested_to and(requested_branch_id is null or coalesce(line.branch_id,entry.branch_id)=requested_branch_id);return result;end;$$;
create function public.accounting_dashboard(requested_organization_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin if(select auth.uid())is null or not private.accounting_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'accounting.read',null)then raise exception'Permission denied.'using errcode='42501';end if;select jsonb_build_object('status',coalesce((select status from public.accounting_settings where organization_id=requested_organization_id),'shadow'),'activationDate',(select activation_date from public.accounting_settings where organization_id=requested_organization_id),'accountCount',(select count(*)from public.accounting_accounts where organization_id=requested_organization_id and is_active),'postedEntries',(select count(*)from public.journal_entries where organization_id=requested_organization_id and status in('posted','reversed')),'pendingEvents',(select count(*)from public.accounting_integration_events where organization_id=requested_organization_id and processing_status in('pending','processing')),'postingExceptions',(select count(*)from public.accounting_posting_exceptions where organization_id=requested_organization_id and status='open'),'openPayables',coalesce((select sum(balance_due)from public.supplier_invoices where organization_id=requested_organization_id and balance_due>0),0),'unmatchedBankTransactions',(select count(*)from public.bank_transactions where organization_id=requested_organization_id and status in('unmatched','partially_matched')))into result;return result;end;$$;

alter table public.accounting_settings enable row level security;alter table public.accounting_accounts enable row level security;alter table public.accounting_periods enable row level security;alter table public.accounting_document_sequences enable row level security;alter table public.journal_entries enable row level security;alter table public.journal_lines enable row level security;alter table public.accounting_posting_exceptions enable row level security;alter table public.opening_balance_imports enable row level security;alter table public.supplier_payments enable row level security;alter table public.supplier_payment_allocations enable row level security;alter table public.bank_accounts enable row level security;alter table public.bank_transactions enable row level security;alter table public.bank_reconciliations enable row level security;alter table public.bank_reconciliation_matches enable row level security;
create policy accounting_settings_read on public.accounting_settings for select to authenticated using(private.accounting_module_enabled(organization_id)and private.can_business_permission(organization_id,'accounting.read',null));
create policy accounting_accounts_read on public.accounting_accounts for select to authenticated using(private.accounting_module_enabled(organization_id)and private.can_business_permission(organization_id,'accounting.read',null));
create policy accounting_periods_read on public.accounting_periods for select to authenticated using(private.accounting_module_enabled(organization_id)and private.can_business_permission(organization_id,'accounting.read',null));
create policy journal_entries_read on public.journal_entries for select to authenticated using(private.accounting_module_enabled(organization_id)and private.can_business_permission(organization_id,'accounting.read',branch_id));
create policy journal_lines_read on public.journal_lines for select to authenticated using(exists(select 1 from public.journal_entries entry where entry.id=journal_lines.entry_id and entry.organization_id=journal_lines.organization_id and private.can_business_permission(journal_lines.organization_id,'accounting.read',entry.branch_id)));
create policy accounting_exceptions_read on public.accounting_posting_exceptions for select to authenticated using(private.accounting_module_enabled(organization_id)and private.can_business_permission(organization_id,'accounting.read',null));
create policy opening_balances_read on public.opening_balance_imports for select to authenticated using(private.accounting_module_enabled(organization_id)and private.can_business_permission(organization_id,'accounting.read',null));
create policy supplier_payments_read on public.supplier_payments for select to authenticated using(private.accounting_module_enabled(organization_id)and private.can_business_permission(organization_id,'accounting.read',branch_id));
create policy supplier_allocations_read on public.supplier_payment_allocations for select to authenticated using(exists(select 1 from public.supplier_payments payment where payment.id=supplier_payment_allocations.payment_id and payment.organization_id=supplier_payment_allocations.organization_id and private.can_business_permission(payment.organization_id,'accounting.read',payment.branch_id)));
create policy bank_accounts_read on public.bank_accounts for select to authenticated using(private.accounting_module_enabled(organization_id)and private.can_business_permission(organization_id,'accounting.read',branch_id));
create policy bank_transactions_read on public.bank_transactions for select to authenticated using(exists(select 1 from public.bank_accounts account where account.id=bank_transactions.bank_account_id and account.organization_id=bank_transactions.organization_id and private.can_business_permission(account.organization_id,'accounting.read',account.branch_id)));
create policy bank_reconciliations_read on public.bank_reconciliations for select to authenticated using(exists(select 1 from public.bank_accounts account where account.id=bank_reconciliations.bank_account_id and account.organization_id=bank_reconciliations.organization_id and private.can_business_permission(account.organization_id,'accounting.read',account.branch_id)));
create policy bank_matches_read on public.bank_reconciliation_matches for select to authenticated using(exists(select 1 from public.bank_reconciliations reconciliation join public.bank_accounts account on account.id=reconciliation.bank_account_id where reconciliation.id=bank_reconciliation_matches.reconciliation_id and reconciliation.organization_id=bank_reconciliation_matches.organization_id and private.can_business_permission(account.organization_id,'accounting.read',account.branch_id)));

revoke all on public.accounting_settings,public.accounting_accounts,public.accounting_periods,public.accounting_document_sequences,public.journal_entries,public.journal_lines,public.accounting_posting_exceptions,public.opening_balance_imports,public.supplier_payments,public.supplier_payment_allocations,public.bank_accounts,public.bank_transactions,public.bank_reconciliations,public.bank_reconciliation_matches from public,anon,authenticated;
grant select on public.accounting_settings,public.accounting_accounts,public.accounting_periods,public.journal_entries,public.journal_lines,public.accounting_posting_exceptions,public.opening_balance_imports,public.supplier_payments,public.supplier_payment_allocations,public.bank_accounts,public.bank_transactions,public.bank_reconciliations,public.bank_reconciliation_matches to authenticated;
revoke all on function private.install_finance_payroll_permissions(uuid),private.handle_main_branch_finance_payroll_permissions(),private.accounting_module_enabled(uuid),private.initialize_supplier_invoice_balance(),private.seed_accounting_accounts(uuid),private.handle_accounting_module_activation(),private.next_accounting_number(uuid,text,date),private.account_by_key(uuid,text),private.ensure_accounting_periods(uuid,date),private.post_journal(uuid,uuid,date,text,uuid,text,text,jsonb,uuid),private.reverse_journal(uuid,uuid,date,text,uuid),private.reject_posted_journal_mutation(),private.reject_journal_line_mutation(),private.emit_operational_accounting_event(),private.post_accounting_event(uuid) from public,anon,authenticated;
grant execute on function private.accounting_module_enabled(uuid) to authenticated;
