grant execute on function public.process_accounting_events(uuid,integer),public.activate_accounting(uuid,date,jsonb),public.save_manual_journal(uuid,uuid,date,text,jsonb,text),public.reverse_journal(uuid,uuid,date,text),public.set_accounting_period_status(uuid,uuid,text),public.record_supplier_payment(uuid,uuid,uuid,date,text,text,numeric,jsonb,text),public.save_bank_account(uuid,uuid,uuid,text,text,text,numeric),public.import_bank_transactions(uuid,uuid,jsonb),public.complete_bank_reconciliation(uuid,uuid,date,numeric,jsonb),public.financial_report(uuid,text,date,date,uuid),public.general_ledger(uuid,uuid,date,date,uuid),public.accounting_dashboard(uuid) to authenticated;
